1	package retention
2	
3	import (
4		"fmt"
5	)
6	
7	// validateBatchInputs 校验一批销毁/核对请求共有的输入：
8	// 申请编号、处理日期、非空且去空白后无重复的档案名单。
9	// 返回去首尾空白后的申请编号、按提交顺序规范化的名单及名单集合。
10	// 任一输入无效即返回错误，调用方不得据此产生部分结果。
11	func validateBatchInputs(applicationID string, processedOn Date, rawIDs []string) (string, []string, map[string]struct{}, error) {
12		appID, err := requireText(applicationID, "申请编号")
13		if err != nil {
14			return "", nil, nil, err
15		}
16		if err := requireDate(processedOn, "处理日期"); err != nil {
17			return "", nil, nil, err
18		}
19		if len(rawIDs) == 0 {
20			return "", nil, nil, fmt.Errorf("retention: 申请 %s 的销毁名单为空: %w",
21				appID, ErrEmptyDestructionList)
22		}
23	
24		// 规范化名单并检查名单内重复（输入校验先于任何业务判断）。
25		// 同一编号仅因首尾空白不同也视为重复。
26		ids := make([]string, 0, len(rawIDs))
27		for _, raw := range rawIDs {
28			id, err := requireText(raw, "档案编号")
29			if err != nil {
30				return "", nil, nil, err
31			}
32			ids = append(ids, id)
33		}
34		seen := make(map[string]struct{}, len(ids))
35		for _, id := range ids {
36			if _, dup := seen[id]; dup {
37				return "", nil, nil, fmt.Errorf("retention: 申请 %s 的销毁名单中档案 %s 重复: %w",
38					appID, id, ErrDuplicateSelection)
39			}
40			seen[id] = struct{}{}
41		}
42		return appID, ids, seen, nil
43	}
44	
45	// Check 在正式办理销毁前做一次只读核对。
46	//
47	// 调用者提交申请编号、处理日期和档案编号名单，得到整批申请能否办理的报告，
48	// 一次看清所有阻碍。核对不销毁档案、不生成或改写清册，也不占用申请编号；
49	// 核对后（无论报告结论如何，甚至读取本地记录失败）仍可沿用同一编号继续
50	// 核对或正式提交。
51	//
52	// 报告区分四种结论：
53	//   - CheckReady 可以办理：申请编号尚未成功使用，名单中每份档案均无阻碍；
54	//   - CheckBlocked 存在阻碍：申请编号尚未成功使用，至少一份档案存在阻碍，
55	//     Results 按提交顺序列出每份档案的核对结果和全部适用阻碍；
56	//   - CheckReplayable 可以取回原清册：申请编号已成功使用，且日期与档案集合
57	//     （顺序无关）与原申请相同，Manifest 返回原清册，不因档案已销毁而判受阻；
58	//   - CheckConflict 申请编号冲突：沿用该编号但改变了日期或集合，Manifest 附原清册。
59	//
60	// 申请编号已被本保管库内任意一条成功的期限修订占用时（与本次选中的档案无关，
61	// 该档案后来再次修订或已销毁都不释放编号），整次核对明确失败，返回
62	// ErrRevisionConflict，报告为空——不列出逐份档案结果，也不附清册。
63	// 只有成功修订才占用编号；失败过的修订提交不影响核对。
64	//
65	// 到期与冻结判断与 Destroy 完全一致：处理日期达到截止日当天即到期，
66	// 任一未解除冻结都会阻止销毁，已解除记录不作为阻碍。
67	//
68	// 申请编号或任一档案编号为空白、日期缺失或不是真实的 YYYY-MM-DD、
69	// 名单为空或含重复编号时，整次核对明确失败，不返回部分报告；
70	// 读取本地记录失败同样明确失败，绝不会用旧报告充当本次结果。
71	//
72	// 报告中的档案结果与清册来自同一次已保存状态读取；报告只说明核对当时的
73	// 情况，之后状态若变化，正式提交仍按最新状态判断。返回值是复制生成的
74	// 只读视图，调用者修改报告或其中清册不影响已保存的历史。
75	func (s *Store) Check(req CheckRequest) (CheckReport, error) {
76		appID, ids, seen, err := validateBatchInputs(req.ApplicationID, req.ProcessedOn, req.ArchiveIDs)
77		if err != nil {
78			return CheckReport{}, err
79		}
80	
81		var report CheckReport
82		err = s.view(func(data *storeData) error {
83			report = CheckReport{
84				ApplicationID: appID,
85				ProcessedOn:   req.ProcessedOn,
86				Results:       make([]ArchiveCheckResult, 0, len(ids)),
87			}
88	
89			// 申请编号已成功使用：只判断能否取回原清册或编号冲突，两者都附原清册。
90			// 原清册取自当前这一次状态读取，与下面逐份核对看到的记录同源。
91			if existing, ok := data.Manifests[appID]; ok {
92				m := manifestFromRecord(existing)
93				report.Manifest = &m
94				if sameApplication(existing, req.ProcessedOn, seen) {
95					report.Status = CheckReplayable
96				} else {
97					report.Status = CheckConflict
98				}
99				return nil
100			}
101	
102			// 申请编号已被任意一条成功的期限修订占用：整次核对失败，报告为空。
103			// 编号占用属于整个保管库，与本次选中的档案无关；失败过的修订不占用编号。
104			if _, rec := findRevision(data, appID); rec != nil {
105				return fmt.Errorf("retention: 申请编号 %s 已用于期限修订: %w",
106					appID, ErrRevisionConflict)
107			}
108	
109			// 申请编号尚未成功使用：按提交顺序逐份核对，每份列出全部适用阻碍。
110			anyBlocked := false
111			for _, id := range ids {
112				r := ArchiveCheckResult{ID: id, Obstructions: []CheckObstruction{}}
113				ar, ok := data.Archives[id]
114				if !ok {
115					// 不存在的编号单独标明，不中断其他档案的核对。
116					r.Obstructions = append(r.Obstructions, CheckObstruction{Kind: ObstructionMissing})
117					anyBlocked = true
118					report.Results = append(report.Results, r)
119					continue
120				}
121				r.Exists = true
122				r.Category = ar.Category
123				r.Start = ar.Start
124				r.End = ar.End
125				r.Destroyed = ar.Destroyed
126	
127				if ar.Destroyed {
128					// 已销毁档案给出所属清册的申请编号和处理日期。
129					obs := CheckObstruction{Kind: ObstructionDestroyed}
130					if rec, ok := data.Manifests[ar.ManifestID]; ok {
131						obs.ManifestApplicationID = rec.ApplicationID
132						obs.ProcessedOn = rec.ProcessedOn
133					} else {
134						obs.ManifestApplicationID = ar.ManifestID
135					}
136					r.Obstructions = append(r.Obstructions, obs)
137					anyBlocked = true
138				} else {
139					// 未到期与未解除冻结可能同时成立，两类问题都要列出。
140					if req.ProcessedOn.Before(ar.End) {
141						r.Obstructions = append(r.Obstructions, CheckObstruction{Kind: ObstructionNotExpired})
142						anyBlocked = true
143					}
144					// 每条未解除冻结各成一条阻碍，顺序沿用冻结历史（登记顺序）。
145					for _, f := range ar.Freezes {
146						if f.Released {
147							continue
148						}
149						r.Obstructions = append(r.Obstructions, CheckObstruction{
150							Kind: ObstructionActiveFreeze,
151							Freeze: ActiveFreezeInfo{
152								FreezeID: f.ID,
153								Reason:   f.Reason,
154								FrozenOn: f.FrozenOn,
155							},
156						})
157						anyBlocked = true
158					}
159				}
160				report.Results = append(report.Results, r)
161			}
162	
163			if anyBlocked {
164				report.Status = CheckBlocked
165			} else {
166				report.Status = CheckReady
167			}
168			return nil
169		})
170		if err != nil {
171			return CheckReport{}, err
172		}
173		return report, nil
174	}
