1	package retention
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"io"
8		"os"
9		"path/filepath"
10		"sync"
11		"syscall"
12	)
13	
14	// 状态文件与锁文件的固定名称，位于调用者选择的本地目录内。
15	const (
16		stateFileName = "retention-state.json"
17		lockFileName  = ".retention.lock"
18	)
19	
20	// Store 是一个本地保管库，对应调用者选择的一个本地保存位置。
21	//
22	// 同一个目录可以被本机上的多个程序（进程）同时打开：
23	// 每次办理都会取得跨进程的排他文件锁，并从磁盘重新读取状态，
24	// 因此两个程序对同一档案的冻结、销毁一定有明确的先后顺序。
25	type Store struct {
26		dir string
27	
28		// opMu 串行化当前 Store 实例内的办理；跨进程互斥由文件锁保证。
29		opMu sync.RWMutex
30	}
31	
32	// Open 打开（或创建）一个本地保存位置。
33	// 目录不存在时会创建；状态文件损坏时返回错误，已有记录不会被覆盖。
34	func Open(dir string) (*Store, error) {
35		if dir == "" {
36			return nil, errors.New("retention: 保存位置不能为空")
37		}
38		if err := os.MkdirAll(dir, 0o755); err != nil {
39			return nil, fmt.Errorf("retention: 无法创建保存位置: %w", err)
40		}
41		s := &Store{dir: dir}
42		// 提前读一次，让损坏的状态文件在打开时就暴露，而不是等到第一次办理。
43		if _, err := s.load(); err != nil {
44			return nil, err
45		}
46		return s, nil
47	}
48	
49	// Close 释放保管库。当前实现没有跨操作持有的资源，保留它以稳定公开入口形态。
50	func (s *Store) Close() error { return nil }
51	
52	func (s *Store) statePath() string { return filepath.Join(s.dir, stateFileName) }
53	func (s *Store) lockPath() string  { return filepath.Join(s.dir, lockFileName) }
54	
55	// lock 取得跨进程排他锁，返回解锁函数。
56	// 每次办理各自加锁、解锁，这样同一位置也允许同进程或跨进程的多个 Store 并存。
57	func (s *Store) lock() (func(), error) {
58		f, err := os.OpenFile(s.lockPath(), os.O_CREATE|os.O_RDWR, 0o600)
59		if err != nil {
60			return nil, fmt.Errorf("retention: 无法打开锁文件: %w", err)
61		}
62		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX); err != nil {
63			f.Close()
64			return nil, fmt.Errorf("retention: 无法取得保存位置锁: %w", err)
65		}
66		return func() {
67			_ = syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
68			_ = f.Close()
69		}, nil
70	}
71	
72	// rlock 取得跨进程共享锁，用于只读核对。
73	func (s *Store) rlock() (func(), error) {
74		f, err := os.OpenFile(s.lockPath(), os.O_CREATE|os.O_RDWR, 0o600)
75		if err != nil {
76			return nil, fmt.Errorf("retention: 无法打开锁文件: %w", err)
77		}
78		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_SH); err != nil {
79			f.Close()
80			return nil, fmt.Errorf("retention: 无法取得保存位置锁: %w", err)
81		}
82		return func() {
83			_ = syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
84			_ = f.Close()
85		}, nil
86	}
87	
88	// load 从磁盘读取最新状态。文件不存在时返回一份空状态。
89	func (s *Store) load() (*storeData, error) {
90		data := newStoreData()
91		f, err := os.Open(s.statePath())
